#!/usr/bin/env Rscript

# Task T041: FDR Overlap Analysis
# Calculates the top-20 CRE overlap percentage between FDR thresholds (0.01, 0.05, 0.10)
# using GLS outputs from T016/T017.
#
# Inputs:  results/gls_results_<stress>.csv (generated by code/06_fit_gls.R)
# Output:  results/fdr_overlap_stats.csv
#
# Dependencies:
#   - T016 (GLS fitting)
#   - T017 (FDR correction)

library(dplyr)
library(readr)
library(tidyr)
library(purrr)

# Configuration
FDR_THRESHOLDS <- c(0.01, 0.05, 0.10)
TOP_N <- 20
OUTPUT_PATH <- "results/fdr_overlap_stats.csv"
INPUT_PATTERN <- "results/gls_results_(.+)\\.csv"

# Helper: Load and process GLS results for a specific stress
load_and_prepare_gls <- function(filepath) {
  if (!file.exists(filepath)) {
    stop(paste("Input file not found:", filepath))
  }

  df <- read_csv(filepath, show_col_types = FALSE)

  # Validate required columns
  required_cols <- c("cre_id", "p_value", "adj_p_value", "beta1")
  missing_cols <- setdiff(required_cols, names(df))
  if (length(missing_cols) > 0) {
    stop(paste("Missing required columns in", filepath, ":", paste(missing_cols, collapse = ", ")))
  }

  # Ensure numeric types
  df <- df %>%
    mutate(
      adj_p_value = as.numeric(adj_p_value),
      beta1 = as.numeric(beta1)
    )

  return(df)
}

# Helper: Get top N CREs sorted by adj_p_value (primary) and |beta1| (tie-breaker)
get_top_cre <- function(df, n, fdr_threshold) {
  # Filter by FDR threshold
  filtered <- df %>%
    filter(!is.na(adj_p_value) & adj_p_value <= fdr_threshold)

  if (nrow(filtered) == 0) {
    return(character(0))
  }

  # Sort: primary = adj_p_value (asc), secondary = |beta1| (desc)
  ranked <- filtered %>%
    arrange(adj_p_value, desc(abs(beta1)))

  # Select top N
  top_cre_ids <- head(ranked$cre_id, n)

  return(top_cre_ids)
}

# Helper: Calculate Jaccard-like overlap percentage between two sets
calculate_overlap_pct <- function(set_a, set_b) {
  if (length(set_a) == 0 || length(set_b) == 0) {
    return(0)
  }
  intersection_size <- length(intersect(set_a, set_b))
  union_size <- length(union(set_a, set_b))
  if (union_size == 0) return(0)
  return((intersection_size / union_size) * 100)
}

main <- function() {
  # Find all GLS result files
  all_files <- list.files(
    path = "results",
    pattern = INPUT_PATTERN,
    full.names = TRUE
  )

  if (length(all_files) == 0) {
    stop("No GLS result files found in results/. Ensure T016/T017 have completed.")
  }

  # Extract stress names
  stress_names <- sub(INPUT_PATTERN, "\\1", basename(all_files))

  cat("Found", length(all_files), "GLS result files for stresses:", paste(stress_names, collapse = ", "), "\n")

  results_list <- list()

  # Process each stress
  for (i in seq_along(stress_names)) {
    stress <- stress_names[i]
    filepath <- all_files[i]

    cat("\nProcessing stress:", stress, "\n")

    # Load data
    df <- load_and_prepare_gls(filepath)

    # Get top CREs for each threshold
    top_sets <- list()
    for (th in FDR_THRESHOLDS) {
      top_sets[[as.character(th)]] <- get_top_cre(df, TOP_N, th)
      cat("  Threshold", th, ": found", length(top_sets[[as.character(th)]]), "top CREs\n")
    }

    # Calculate pairwise overlaps
    overlap_matrix <- matrix(NA, nrow = length(FDR_THRESHOLDS), ncol = length(FDR_THRESHOLDS))
    rownames(overlap_matrix) <- as.character(FDR_THRESHOLDS)
    colnames(overlap_matrix) <- as.character(FDR_THRESHOLDS)

    for (th1 in FDR_THRESHOLDS) {
      for (th2 in FDR_THRESHOLDS) {
        pct <- calculate_overlap_pct(top_sets[[as.character(th1)]], top_sets[[as.character(th2)]])
        overlap_matrix[as.character(th1), as.character(th2)] <- pct
      }
    }

    # Store results for this stress
    results_list[[stress]] <- list(
      stress = stress,
      overlap_matrix = overlap_matrix,
      top_sets = top_sets
    )
  }

  # Flatten results into a tidy dataframe for output
  output_rows <- list()

  for (stress in names(results_list)) {
    res <- results_list[[stress]]
    mat <- res$overlap_matrix

    for (th1 in FDR_THRESHOLDS) {
      for (th2 in FDR_THRESHOLDS) {
        output_rows[[length(output_rows) + 1]] <- data.frame(
          stress = stress,
          threshold_a = as.numeric(th1),
          threshold_b = as.numeric(th2),
          overlap_percentage = mat[as.character(th1), as.character(th2)]
        )
      }
    }
  }

  final_df <- bind_rows(output_rows)

  # Ensure output directory exists
  dir.create("results", showWarnings = FALSE, recursive = TRUE)

  # Write output
  write_csv(final_df, OUTPUT_PATH)

  cat("\nSuccessfully wrote FDR overlap statistics to:", OUTPUT_PATH, "\n")
  cat("Summary:\n")
  print(final_df)
}

# Run main if executed as script
if (!interactive()) {
  main()
}
